#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# Retired 2026-09-25: the owner hand-tunes the box, and a run of this script would overwrite
# that work. Only the owner runs it, by hand, with LIQFADE_OWNER_RUN=1 (CLAUDE.md section 6).
if [ "${LIQFADE_OWNER_RUN:-}" != "1" ]; then
  echo "refused: the owner manages the VPS by hand. Owner only: rerun with LIQFADE_OWNER_RUN=1." >&2
  exit 1
fi

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# liqfade Phase 1: a fresh Ubuntu 24.04 VPS in Tokyo recording market data 24/7.
#
#   bash scripts/wizard_phase1_recorder.sh
#
# Every stage checks its own result before the next one starts, and stops with the
# command that shows you why when a check fails. Re-running is safe: each stage
# recognises work that is already done. Nothing here touches liqfade-live, ever.
#
# Secrets you type are piped straight into /srv/liqfade/.env on the VPS over ssh.
# They are never written to this machine, never passed in a command argument, and
# never printed. The only local file this writes is .env.wizard, which holds the
# host, the ssh port and the Tailscale address: nothing secret.

TOTAL_STAGES=15
ENV_FILE=".env.wizard"                # gitignored by the .env.* rule; non-secret notes
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
APP_ROOT="/srv/liqfade"
REMOTE_HELPER="/root/.liqfade-wizard.py"
PANEL_PORT=8787
TUNNEL_SOCKET="${TMPDIR:-/tmp}/liqfade-panel-tunnel"
SSH_OPTS=(-o ConnectTimeout=10 -o PasswordAuthentication=no -o KbdInteractiveAuthentication=no)

# ── result reporting ───────────────────────────────────────────────────────

ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
bad() { printf '  %s✗%s %s\n' "$RED" "$RESET" "$1"; }
die() {
  bad "$1"
  printf '\n  %sStopped in stage %s/%s. Fix that, then run this wizard again:\n' \
    "$DIM" "$_STAGE_INDEX" "$TOTAL_STAGES"
  printf '  it re-checks everything and picks up where you left off.%s\n\n' "$RESET"
  exit 1
}

# ── talking to the box ─────────────────────────────────────────────────────
# Always as root, always on the current ssh port, always to the public address.
# The panel tunnel in stage 12 goes over Tailscale when this Mac can reach the
# tailnet, and over the public address when a VPN firewall blocks it (stage 4
# decides). The panel itself only ever binds 127.0.0.1 on the VPS.

ssh_at() { local port="$1" host="$2"; shift 2; ssh -p "$port" "${SSH_OPTS[@]}" "root@$host" "$@"; }
RSH()  { ssh_at "$SSH_PORT" "$VPS_HOST" "$@"; }
RSHT() { ssh -t -p "$SSH_PORT" "${SSH_OPTS[@]}" "root@$VPS_HOST" "$@"; }

# rpy SUBCOMMAND [ARG...] runs the remote helper. Arguments are quoted for the
# remote shell; secrets go on stdin, never here.
rpy() { RSH "python3 $REMOTE_HELPER $(printf '%q ' "$@")"; }

# secret_to_box KEY: read a hidden value and upsert it into the VPS .env.
# Empty input keeps whatever the box already has, so re-runs need no retyping.
secret_to_box() {
  local key="$1" prompt="$2" value=""
  if rpy env-has "$key" >/dev/null 2>&1; then
    printf '  %s%s%s %s[Enter keeps the value already on the box]%s ' \
      "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs value || true
  printf '\n'
  if [[ -z "$value" ]]; then
    rpy env-has "$key" >/dev/null 2>&1 || die "$key is not set on the box and you entered nothing"
    ok "$key: kept the value already in $APP_ROOT/.env"
    return
  fi
  printf '%s' "$value" | RSH "python3 $REMOTE_HELPER env-set $key" >/dev/null \
    || die "could not write $key into $APP_ROOT/.env"
  ok "$key written to $APP_ROOT/.env (0600, owned by liqfade)"
}

# push_helper installs the remote check script. One file, root only, no secrets in it.
push_helper() {
  RSH "cat > $REMOTE_HELPER && chmod 0700 $REMOTE_HELPER" <<'PYEOF'
#!/usr/bin/env python3
"""Remote checks for the liqfade Phase 1 wizard. Installed at /root/.liqfade-wizard.py.

Every secret is read from /srv/liqfade/.env or piped in on stdin. Nothing secret is
ever taken from argv, printed, or written anywhere else. Read-only about systemd: it
reports what units are doing and never starts, stops or edits one.
"""

from __future__ import annotations

import json
import os
import pwd
import subprocess
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

APP = Path("/srv/liqfade")
ENV = APP / ".env"
DATA = APP / "data"
LAKE = DATA / "parquet"
STATE = DATA / "state.json"
VENV_PY = APP / "app/.venv/bin/python"
USER = "liqfade"
UNITS = ("liqfade-recorder", "liqfade-panel", "liqfade-live", "liqfade-watchdog")

# venue -> (table its rows land in, whether an empty hour is normal)
VENUES = {
    "hyperliquid": ("trades", False),
    "bybit": ("liquidations", False),
    "binance": ("liquidations", True),
    "okx": ("liquidations", True),
    "coinalyze": ("xchg_ctx", False),
}
REQUIRED_ENV = (
    "LIQFADE_ENV",
    "LIQFADE_DATA_DIR",
    "COINALYZE_API_KEY",
    "TELEGRAM_BOT_TOKEN",
    "TELEGRAM_ALERT_CHAT_ID",
)


def fail(msg: str) -> None:
    print(msg)
    raise SystemExit(1)


def read_env() -> dict[str, str]:
    out: dict[str, str] = {}
    if not ENV.exists():
        return out
    for line in ENV.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        out[key.strip()] = value.strip().strip('"').strip("'")
    return out


def own(path: Path, mode: int) -> None:
    entry = pwd.getpwnam(USER)
    os.chown(path, entry.pw_uid, entry.pw_gid)
    os.chmod(path, mode)


def env_set(key: str, value: str) -> None:
    lines = ENV.read_text().splitlines() if ENV.exists() else []
    kept = [line for line in lines if line.split("=", 1)[0].strip() != key]
    tmp = ENV.with_name(".env.wizard.tmp")
    tmp.write_text("\n".join([*kept, f"{key}={value}"]) + "\n")
    own(tmp, 0o600)
    tmp.replace(ENV)


def http(url: str, *, headers: dict[str, str] | None = None, data: bytes | None = None,
         timeout: float = 15.0) -> tuple[int, str]:
    request = urllib.request.Request(url, data=data, headers=headers or {})
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.status, response.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as exc:  # a status is an answer, not a crash
        return exc.code, exc.read().decode("utf-8", "replace")
    except Exception as exc:  # noqa: BLE001 - the caller only ever reports this
        return 0, f"{type(exc).__name__}: {exc}"


def telegram(method: str, payload: dict[str, object] | None = None) -> tuple[int, dict]:
    token = read_env().get("TELEGRAM_BOT_TOKEN", "")
    if not token:
        fail("TELEGRAM_BOT_TOKEN is not set in /srv/liqfade/.env")
    body = json.dumps(payload or {}).encode()
    code, text = http(
        f"https://api.telegram.org/bot{token}/{method}",
        headers={"Content-Type": "application/json"},
        data=body,
    )
    try:
        return code, json.loads(text)
    except ValueError:
        # Never echo the body: a transport error page could quote the request URL.
        return code, {"ok": False, "description": f"unparseable response ({len(text)} bytes)"}


def run(argv: list[str], **kwargs) -> subprocess.CompletedProcess:
    return subprocess.run(argv, capture_output=True, text=True, check=False, **kwargs)


def state() -> dict:
    if not STATE.exists():
        fail(f"no {STATE}: the recorder has not written a state snapshot yet")
    snapshot = json.loads(STATE.read_text())
    age_s = time.time() - snapshot["ts_ms"] / 1000.0
    snapshot["_age_s"] = age_s
    return snapshot


# --- subcommands -------------------------------------------------------------


def cmd_env_seed() -> None:
    """Create /srv/liqfade/.env from the .env.example piped in, if it is not there."""
    if ENV.exists():
        print("env: already present, left untouched")
    else:
        ENV.write_text(sys.stdin.read())
        own(ENV, 0o600)
        print("env: created from .env.example")
    stat = ENV.stat()
    print(f"env: mode {stat.st_mode & 0o777:o}, owner {pwd.getpwuid(stat.st_uid).pw_name}")
    if stat.st_mode & 0o777 != 0o600 or pwd.getpwuid(stat.st_uid).pw_name != USER:
        fail("env: wrong mode or owner, expected 0600 and liqfade")


def cmd_env_set(key: str) -> None:
    env_set(key, sys.stdin.read().strip())
    print(f"env: {key} set")


def cmd_env_has(key: str) -> None:
    if not read_env().get(key, ""):
        fail(f"env: {key} is empty or missing")
    print(f"env: {key} is set")


def cmd_env_audit() -> None:
    """Which required keys are set. Never prints a value."""
    values = read_env()
    missing = [key for key in REQUIRED_ENV if not values.get(key, "")]
    for key in REQUIRED_ENV:
        print(f"  {'set  ' if values.get(key) else 'EMPTY'}  {key}")
    if values.get("LIQFADE_ENV") != "paper":
        fail(f"env: LIQFADE_ENV is {values.get('LIQFADE_ENV')!r}, expected paper for Phase 1")
    if values.get("LIQFADE_LIVE_TRADING", ""):
        fail("env: LIQFADE_LIVE_TRADING is set. Phase 1 records data and places no orders.")
    if values.get("LIQFADE_DATA_DIR") != str(DATA):
        fail(f"env: LIQFADE_DATA_DIR must be {DATA} (the units can only write there)")
    if missing:
        fail("env: still empty: " + ", ".join(missing))
    print("env: every key Phase 1 needs is set, and live trading is off")


def cmd_tailscale() -> None:
    result = run(["tailscale", "status", "--json"])
    if result.returncode != 0:
        fail("tailscale: not up yet (" + (result.stderr.strip() or "no output") + ")")
    status = json.loads(result.stdout)
    backend = status.get("BackendState", "?")
    self_node = status.get("Self") or {}
    name = (self_node.get("DNSName") or "").rstrip(".")
    ips = [ip for ip in (self_node.get("TailscaleIPs") or []) if ":" not in ip]
    print(f"state={backend} name={name} ip={ips[0] if ips else ''}")
    if backend != "Running" or not ips:
        fail("tailscale: not connected")


def cmd_coinalyze() -> None:
    key = read_env().get("COINALYZE_API_KEY", "")
    if not key:
        fail("coinalyze: COINALYZE_API_KEY is not set")
    code, body = http("https://api.coinalyze.net/v1/exchanges", headers={"api_key": key})
    if code != 200:
        fail(f"coinalyze: the API answered {code or 'nothing'} ({body[:120]})")
    print(f"coinalyze: key accepted, {len(json.loads(body))} exchanges listed")


def cmd_tg_chats() -> None:
    code, body = telegram("getUpdates")
    if code != 200 or not body.get("ok"):
        fail(f"telegram: getUpdates answered {code} ({body.get('description', '')})")
    chats = {}
    for update in body.get("result", []):
        for key in ("message", "edited_message", "channel_post"):
            chat = update.get(key, {}).get("chat")
            if chat:
                label = chat.get("username") or chat.get("title") or chat.get("first_name") or "?"
                chats[str(chat["id"])] = label
    if not chats:
        fail("telegram: no messages yet")
    for chat_id, label in chats.items():
        print(f"{chat_id} {label}")


def cmd_tg_send(text: str) -> None:
    chat_id = read_env().get("TELEGRAM_ALERT_CHAT_ID", "")
    if not chat_id:
        fail("telegram: TELEGRAM_ALERT_CHAT_ID is not set")
    code, body = telegram("sendMessage", {"chat_id": chat_id, "text": text})
    if code != 200 or not body.get("ok"):
        fail(f"telegram: sendMessage answered {code} ({body.get('description', '')})")
    print("telegram: message accepted by the Bot API")


def cmd_deploy_key() -> None:
    """A read-only deploy key for the box, so the liqfade user can clone the repo."""
    home = Path(pwd.getpwnam(USER).pw_dir)
    ssh_dir = home / ".ssh"
    key = ssh_dir / "id_ed25519"
    ssh_dir.mkdir(mode=0o700, exist_ok=True)
    own(ssh_dir, 0o700)
    if not key.exists():
        result = run(["ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-C",
                      "liqfade-vps-deploy", "-f", str(key)])
        if result.returncode != 0:
            fail(f"ssh-keygen failed: {result.stderr.strip()}")
        own(key, 0o600)
        own(key.with_suffix(".pub"), 0o644)
    known = ssh_dir / "known_hosts"
    if "github.com" not in (known.read_text() if known.exists() else ""):
        scan = run(["ssh-keyscan", "-t", "rsa,ecdsa,ed25519", "github.com"])
        with known.open("a") as handle:
            handle.write(scan.stdout)
        own(known, 0o644)
    print(key.with_suffix(".pub").read_text().strip())


def cmd_git_auth() -> None:
    result = run(["su", "-s", "/bin/bash", "-c",
                  "ssh -o BatchMode=yes -o StrictHostKeyChecking=yes -T git@github.com", USER])
    output = (result.stdout + result.stderr).strip()
    if "successfully authenticated" not in output:
        fail(f"github: the box cannot read the repo yet ({output.splitlines()[-1] if output else '?'})")
    print(f"github: {output.splitlines()[-1]}")


def cmd_units() -> None:
    """Read only. Reports what each unit is doing; starts and stops nothing."""
    problems = []
    for unit in UNITS:
        active = run(["systemctl", "is-active", unit]).stdout.strip() or "unknown"
        enabled = run(["systemctl", "is-enabled", unit]).stdout.strip() or "unknown"
        restarts = run(["systemctl", "show", "-p", "NRestarts", "--value", unit]).stdout.strip()
        print(f"  {unit:<20} {active:<12} {enabled:<10} restarts={restarts or 0}")
        if unit in ("liqfade-live", "liqfade-watchdog") and active in ("active", "activating"):
            problems.append(unit)
    if problems:
        print("\n  Phase 5 and 6 units are running that have no code behind them yet:")
        print(f"    {', '.join(problems)}")
        print("  They will restart-loop and fill the journal. This wizard will not touch")
        print("  them. To stop them yourself, on the VPS as root:")
        print(f"    systemctl disable --now {' '.join(problems)}")


def cmd_feeds() -> None:
    snapshot = state()
    feeds = snapshot.get("feeds", [])
    if not feeds:
        fail("no feeds in the state snapshot: the recorder has not subscribed yet")
    print(f"  snapshot {snapshot['_age_s']:.1f}s old, {len(feeds)} streams\n")
    down = []
    for feed in sorted(feeds, key=lambda f: f["name"]):
        mark = "ok  " if feed["connected"] else "DOWN"
        print(f"  {feed['name']:<26} {mark}  lag={feed['lag_ms'] / 1000:>7.1f}s"
              f"  msgs_1m={feed['msgs_1m']:>6}  gaps_1h={feed['gaps_1h']}")
        if not feed["connected"]:
            down.append(feed["name"])
    if snapshot["_age_s"] > 10:
        fail(f"the state snapshot is {snapshot['_age_s']:.0f}s old: the recorder is stalled")
    if down:
        fail("not connected: " + ", ".join(down))
    print("\n  every stream connected")


def cmd_binance() -> None:
    """Does Binance answer from this datacenter at all? 451 means geo-blocked."""
    code, _ = http("https://fapi.binance.com/fapi/v1/ping")
    print(f"  REST  fapi.binance.com/fapi/v1/ping -> {code or 'no answer'}")
    feed = next((f for f in state().get("feeds", []) if f["name"] == "binance.liquidations"), None)
    if feed:
        seen = "never" if not feed["last_msg_ms"] else f"{feed['lag_ms'] / 60000:.1f} min ago"
        print(f"  WS    binance.liquidations connected={feed['connected']}  last message {seen}"
              f"  msgs_1m={feed['msgs_1m']}")
    if code == 451:
        fail("  verdict: Binance geo-blocks this datacenter. Its liquidation feed is unusable "
             "from here; weight it out in config or move the recorder.")
    if code != 200:
        fail(f"  verdict: no usable answer from Binance ({code}). Check egress from the box.")
    if feed and feed["connected"] and not feed["last_msg_ms"]:
        print("  verdict: Binance reachable and the socket is open, but no liquidation has "
              "arrived yet. That is normal in a calm hour; check again after one.")
        return
    print("  verdict: Binance flows from Tokyo")


def cmd_parquet() -> None:
    """One Parquet file per venue in the hour partitions the recorder has flushed.

    Only today and yesterday are looked at. Older days have been through the nightly
    compaction, which folds a multi-venue table into one `all_day.parquet` and so drops
    the venue from the file name; counting venues in there needs a duckdb query, which
    is a laptop job, not a deployment check.
    """
    if not LAKE.exists():
        fail(f"no lake at {LAKE} yet: the recorder flushes on the UTC hour boundary")
    days = [time.strftime("%Y-%m-%d", time.gmtime(time.time() - offset)) for offset in (0, 86400)]
    missing_hard, missing_soft, compacted = [], [], []
    for venue, (table, sparse) in VENUES.items():
        dirs = [LAKE / table / f"date={day}" for day in days]
        files = sorted(path for directory in dirs for path in directory.glob(f"{venue}_*.parquet"))
        folded = sorted(path for directory in dirs for path in directory.glob("*_day.parquet"))
        size = sum(path.stat().st_size for path in files)
        newest = f"{files[-1].parent.name}/{files[-1].name}" if files else "-"
        print(f"  {venue:<12} {table:<14} {len(files):>3} file(s)  {size / 1e6:>8.2f} MB  {newest}")
        if files:
            continue
        if folded:
            compacted.append(f"{venue} ({folded[-1].parent.name}/{folded[-1].name})")
        else:
            (missing_soft if sparse else missing_hard).append(venue)
    if compacted:
        print("\n  already compacted, so the venue is inside the file rather than its name: "
              + ", ".join(compacted))
    if missing_soft:
        print("\n  no file yet for: " + ", ".join(missing_soft) +
              ". These feeds only write when a liquidation happens, so an empty hour is "
              "a quiet market, not a fault. Check again after a volatile one.")
    if missing_hard:
        fail("\n  nothing written for: " + ", ".join(missing_hard) +
             ". These stream constantly, so a missing file is a real problem: "
             "journalctl -u liqfade-recorder -n 100")
    print("\n  every constant stream has written Parquet")


def cmd_alert_flag(action: str) -> None:
    """The disk-alert flag the VPS cron writes. The recorder alerts on it within 5 min."""
    flag = DATA / "ALERT_DISK"
    if action == "on":
        flag.write_text("liqfade wizard: Telegram test, not a real disk problem\n")
        own(flag, 0o644)
        print(f"wrote {flag}")
    else:
        flag.unlink(missing_ok=True)
        print(f"removed {flag}")


def cmd_alert_seen(since: str) -> None:
    result = run(["journalctl", "-u", "liqfade-recorder", "--since", f"@{since}", "-o", "cat"])
    hits = [line for line in result.stdout.splitlines() if "alert_sent" in line]
    if not hits:
        fail("no alert_sent in the recorder journal yet")
    print(hits[-1][:300])


def cmd_panel_hash() -> None:
    """bcrypt the panel password with the app's own code. Password in, hash out, no disk."""
    if not VENV_PY.exists():
        fail(f"no {VENV_PY}: deploy has not run yet")
    program = ("import sys;from liqfade.panel.auth import hash_password;"
               "sys.stdout.write(hash_password(sys.stdin.read().strip()))")
    result = run([str(VENV_PY), "-c", program], input=sys.stdin.read(), cwd=str(APP / "app"))
    if result.returncode != 0 or not result.stdout.startswith("$2"):
        fail(f"hashing failed: {result.stderr.strip()[:200]}")
    print(result.stdout.strip())


def cmd_panel_health() -> None:
    code, body = http("http://127.0.0.1:8787/api/health", timeout=5.0)
    if code != 200:
        fail(f"panel: /api/health answered {code or 'nothing'}: "
             "journalctl -u liqfade-panel -n 50")
    print(f"panel: {body.strip()}")


def cmd_deployed() -> None:
    venv = APP / "app/.venv/bin/liqfade"
    if not venv.exists():
        fail(f"no {venv}: the deploy did not finish")
    head = run(["su", "-s", "/bin/bash", "-c",
                f"cd {APP / 'app'} && git log -1 --oneline", USER]).stdout.strip()
    print(f"  code:  {head}")
    print(f"  venv:  {venv}")
    for unit in UNITS:
        path = Path("/etc/systemd/system") / f"{unit}.service"
        if not path.exists():
            fail(f"  unit {path} was not installed")
    print("  units: all four service files installed")


COMMANDS = {
    "env-seed": cmd_env_seed,
    "env-set": cmd_env_set,
    "env-has": cmd_env_has,
    "env-audit": cmd_env_audit,
    "tailscale": cmd_tailscale,
    "coinalyze": cmd_coinalyze,
    "tg-chats": cmd_tg_chats,
    "tg-send": cmd_tg_send,
    "deploy-key": cmd_deploy_key,
    "git-auth": cmd_git_auth,
    "units": cmd_units,
    "feeds": cmd_feeds,
    "binance": cmd_binance,
    "parquet": cmd_parquet,
    "alert-flag": cmd_alert_flag,
    "alert-seen": cmd_alert_seen,
    "panel-hash": cmd_panel_hash,
    "panel-health": cmd_panel_health,
    "deployed": cmd_deployed,
}

if __name__ == "__main__":
    if len(sys.argv) < 2 or sys.argv[1] not in COMMANDS:
        fail(f"usage: {sys.argv[0]} {{{'|'.join(COMMANDS)}}} [arg]")
    COMMANDS[sys.argv[1]](*sys.argv[2:])
PYEOF
}

# ── stages ─────────────────────────────────────────────────────────────────

banner "liqfade Phase 1: the recorder on a Tokyo VPS"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "The server"
say "One small box in Tokyo, because Hyperliquid's API and validators are there."
say "2 vCPU, 4 GB RAM, 80 GB disk, Ubuntu 24.04. \$12 to \$24 a month."
step "Create it with YOUR SSH PUBLIC KEY attached. The hardening script turns"
step "password login off, so a box without your key is a box you cannot enter."
note "Vultr Tokyo and AWS Lightsail Tokyo both fit the budget."
if confirm "Open the Vultr deploy page? (n if you use Lightsail or already have the box)"; then
  open_url "https://my.vultr.com/deploy/"
fi
ask VPS_HOST "Server public IP or hostname:"
[[ -n "$VPS_HOST" ]] || die "no address given"
write_env VPS_HOST "$VPS_HOST"

SSH_PORT="$(_existing SSH_PORT || echo 22)"
printf '\n'
say "Checking root ssh. Accept the host fingerprint if it asks."
if ssh_at "$SSH_PORT" "$VPS_HOST" true; then
  ok "root ssh works on port $SSH_PORT"
elif [[ "$SSH_PORT" != "22" ]] && ssh_at 22 "$VPS_HOST" true; then
  SSH_PORT=22
  ok "root ssh works on port 22, so the box is not hardened yet"
else
  die "cannot ssh to root@$VPS_HOST. Is your key on the box and the firewall open?"
fi
pause "Press Enter for the next stage."

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Harden it"
say "Runs scripts/vps_bootstrap.sh on the box: the liqfade user, /srv/liqfade,"
say "uv, Tailscale, ufw, fail2ban, unattended upgrades, chrony, logrotate, and"
say "SSH moved off port 22 with password login switched off."
if [[ "$SSH_PORT" == "22" ]]; then
  ask NEW_SSH_PORT "SSH port to move to [2222]:"
  NEW_SSH_PORT="${NEW_SSH_PORT:-2222}"
  printf '\n'
  RSH "bash -s -- $NEW_SSH_PORT" < "$REPO_ROOT/scripts/vps_bootstrap.sh" \
    || die "the bootstrap script failed. Nothing has been moved; read the output above."
  printf '\n'
  if ssh_at "$NEW_SSH_PORT" "$VPS_HOST" true; then
    SSH_PORT="$NEW_SSH_PORT"
    ok "root ssh proven on the new port $SSH_PORT"
  else
    die "port $NEW_SSH_PORT does not answer. Your old session on 22 still works: keep it open and check sshd there."
  fi
else
  ok "ssh already answers on $SSH_PORT, so the bootstrap has run here before"
  if confirm "Run it again anyway? It is idempotent and repairs a half-finished run."; then
    printf '\n'
    RSH "bash -s -- $SSH_PORT" < "$REPO_ROOT/scripts/vps_bootstrap.sh" \
      || die "the bootstrap script failed. Read the output above."
    ssh_at "$SSH_PORT" "$VPS_HOST" true || die "ssh on $SSH_PORT stopped working"
    ok "bootstrap re-run, ssh still good"
  fi
fi
write_env SSH_PORT "$SSH_PORT"

if RSH "ufw status | grep -q '^22/tcp'"; then
  printf '\n'
  say "Port 22 is still open in the firewall. It exists only as your way back in"
  say "while the new port is unproven. The new port is proven now."
  if confirm "Close port 22?"; then
    RSH "ufw delete allow 22/tcp" >/dev/null || die "ufw delete failed"
    if RSH "ufw status | grep -q '^22/tcp'"; then die "port 22 is still in the ruleset"; fi
    ok "port 22 closed"
  else
    SKIPPED+=("close port 22 on the VPS: ufw delete allow 22/tcp")
    warn "leaving port 22 open. Close it once you are confident."
  fi
fi

push_helper || die "could not install the check helper on the box"
ok "check helper installed at $REMOTE_HELPER"
pause "Press Enter for the next stage."

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Tailscale on the VPS (optional)"
say "A private network between the laptop and the box, used for the panel tunnel"
say "when it is available. Never required: the tunnel is the same key-only ssh"
say "over the public address otherwise."
TS_IP=""; TS_NAME=""
if TS_LINE="$(rpy tailscale 2>/dev/null)"; then
  TS_IP="${TS_LINE##*ip=}"
  TS_NAME="${TS_LINE#*name=}"; TS_NAME="${TS_NAME%% *}"
  write_env TS_IP "$TS_IP"
  write_env TS_NAME "$TS_NAME"
  ok "VPS on the tailnet as $TS_NAME ($TS_IP)"
else
  warn "the box is not on a tailnet; skipping. To add it later: ssh in and run"
  warn "  tailscale up --ssh=false"
fi
pause "Press Enter for the next stage."

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Which address the tunnel uses"
# Tailscale is preferred when both ends have it and this Mac can actually push
# packets through it. A VPN firewall on the Mac drops every
# packet that is not its own, tailnet included; a closed Tailscale app is the same
# outcome. Every failure lands on the public address: the same key-only ssh on the
# same port behind the same fail2ban, just with no private network in front.
TUNNEL_HOST="$VPS_HOST"; TUNNEL_VIA="the public address"
TS_BIN="$(command -v tailscale || true)"
if [[ -z "$TS_BIN" && -x /Applications/Tailscale.app/Contents/MacOS/Tailscale ]]; then
  TS_BIN=/Applications/Tailscale.app/Contents/MacOS/Tailscale
fi
if [[ -n "$TS_IP" && -n "$TS_BIN" ]] && "$TS_BIN" status 2>/dev/null | grep -q "$TS_IP" \
   && ssh_at "$SSH_PORT" "$TS_IP" true 2>/dev/null; then
  TUNNEL_HOST="$TS_IP"; TUNNEL_VIA="Tailscale"
  ok "ssh over Tailscale works; the tunnel will use $TS_IP"
else
  ok "the tunnel and the sync will use the public address $VPS_HOST"
  note "key-only ssh on port $SSH_PORT behind fail2ban; Tailscale is not needed"
fi
write_env TUNNEL_HOST "$TUNNEL_HOST"
pause "Press Enter for the next stage."

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "The secrets file on the box"
say "$APP_ROOT/.env, mode 0600, owned by liqfade, seeded from .env.example so"
say "every variable the code reads is documented in it."
rpy env-seed < "$REPO_ROOT/.env.example" || die "could not create $APP_ROOT/.env"
warn "Values you type from here on go straight into that file over ssh."
note "They are never written to this Mac and never shown on screen."
pause "Press Enter for the next stage."

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Coinalyze API key"
say "Free tier. Cross-exchange open interest and funding, polled every 60s."
open_url "https://coinalyze.net/futures-data/api/"
step "Sign in, then copy the API key from the API page."
secret_to_box COINALYZE_API_KEY "Paste the Coinalyze API key:"
rpy coinalyze || die "Coinalyze rejected the key, or the box cannot reach the API"
pause "Press Enter for the next stage."

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Telegram bot"
say "How the recorder tells you a stream went silent or the disk filled up."
open_url "https://t.me/BotFather"
step "Send /newbot, pick a name, and copy the token BotFather gives you."
secret_to_box TELEGRAM_BOT_TOKEN "Paste the bot token:"
printf '\n'
step "Now open your new bot in Telegram and send it any message, so it learns"
step "your chat id. The wizard reads the id from the bot; you do not type it."
CHAT_LINE=""
for attempt in 1 2 3 4 5 6; do
  pause "Sent it? Press Enter to look."
  if CHATS="$(rpy tg-chats)"; then
    CHAT_LINE="$(printf '%s\n' "$CHATS" | head -1)"
    break
  fi
  CHAT_LINE=""
  warn "nothing from Telegram yet (try $attempt of 6)"
done
[[ -n "$CHAT_LINE" ]] || die "no message reached the bot. Check the token, and that you messaged the right bot."
CHAT_ID="${CHAT_LINE%% *}"
if [[ "$(printf '%s\n' "$CHATS" | wc -l | tr -d ' ')" != "1" ]]; then
  printf '\n'
  say "Your bot has talked to more than one chat:"
  printf '%s\n' "$CHATS" | sed 's/^/    /'
  ask CHAT_PICK "Which chat id gets the alerts? [Enter for $CHAT_ID]:"
  CHAT_ID="${CHAT_PICK:-$CHAT_ID}"
fi
ok "chat id $CHAT_ID (${CHAT_LINE#* })"
printf '%s' "$CHAT_ID" | RSH "python3 $REMOTE_HELPER env-set TELEGRAM_ALERT_CHAT_ID" >/dev/null
printf '%s' "$CHAT_ID" | RSH "python3 $REMOTE_HELPER env-set TELEGRAM_ALLOWED_CHAT_IDS" >/dev/null
ok "alert chat id and the command allowlist written to $APP_ROOT/.env"
rpy tg-send "liqfade wizard: Telegram is wired up. Nothing is trading." \
  || die "the Bot API refused the message"
confirm "Did that message arrive in Telegram?" || die "the API accepted it but you did not get it: check you messaged the right bot"
printf '\n'
say "Checking the whole file now, without printing any value:"
rpy env-audit || die "$APP_ROOT/.env is not complete yet"
pause "Press Enter for the next stage."

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Let the box read the repo"
DEFAULT_REPO="$(git -C "$REPO_ROOT" remote get-url origin 2>/dev/null || echo '')"
say "The deploy clones the repo as the liqfade user, which has no keys of its own."
if [[ -n "$DEFAULT_REPO" ]]; then note "this clone's origin: $DEFAULT_REPO"; fi
ask REPO_URL "Repo URL to deploy from${DEFAULT_REPO:+ [Enter for origin]}:"
REPO_URL="${REPO_URL:-$DEFAULT_REPO}"
[[ -n "$REPO_URL" ]] || die "no repo URL"
write_env REPO_URL "$REPO_URL"
if [[ "$REPO_URL" == git@* || "$REPO_URL" == ssh://* ]]; then
  say "An SSH URL, so the box needs a read-only deploy key. Generating one:"
  DEPLOY_KEY="$(rpy deploy-key)" || die "could not generate a deploy key on the box"
  printf '\n%s\n\n' "$DEPLOY_KEY"
  if [[ "$REPO_URL" == *github.com* ]]; then
    SLUG="${REPO_URL#*:}"; SLUG="${SLUG#//github.com/}"; SLUG="${SLUG%.git}"
    open_url "https://github.com/$SLUG/settings/keys"
    step "Add deploy key → paste the line above → leave 'Allow write access' OFF."
    pause "Added it? Press Enter to check."
    rpy git-auth || die "GitHub still refuses the box's key"
  else
    step "Add the line above as a READ-ONLY deploy key on your git host."
    pause "Added it? Press Enter to continue."
    warn "not GitHub, so the key check is skipped; the deploy in stage 9 will prove it."
  fi
else
  ok "an HTTPS URL: nothing to set up if the repo is public"
  warn "if it is private, HTTPS needs a token in the URL. An SSH URL is easier."
fi
pause "Press Enter for the next stage."

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "Deploy"
say "Clones the repo as the liqfade user, installs the locked dependencies, and"
say "installs the four unit files. It does not enable live trading: that needs"
say "LIQFADE_ENV=mainnet, LIQFADE_LIVE_TRADING=1 and no data/KILL file, and this"
say "box has none of the three."
printf '\n'
RSH "LIQFADE_REPO_URL='$REPO_URL' bash -s" < "$REPO_ROOT/scripts/deploy.sh" \
  || die "the deploy failed. The output above says where."
printf '\n'
rpy deployed || die "the deploy did not leave the box in the expected state"
printf '\n'
say "What the units are doing. This is a read-only look: the wizard starts only"
say "the recorder and the panel, and never touches liqfade-live."
rpy units
pause "Press Enter for the next stage."

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "Panel password"
say "The panel refuses to start without a password hash. Pick one now: it is"
say "hashed on the box with the app's own bcrypt code, and only the hash is stored."
while :; do
  ask_secret PANEL_PW "Choose a panel password:"
  ask_secret PANEL_PW2 "Repeat it:"
  # shellcheck disable=SC2153  # ask_secret assigns via printf -v, which shellcheck cannot see
  if [[ -n "$PANEL_PW" && "$PANEL_PW" == "$PANEL_PW2" ]]; then break; fi
  warn "empty or the two did not match, try again"
done
PANEL_HASH="$(printf '%s' "$PANEL_PW" | RSH "python3 $REMOTE_HELPER panel-hash")" \
  || die "hashing the password on the box failed"
printf '%s' "$PANEL_HASH" | RSH "python3 $REMOTE_HELPER env-set LIQFADE_PANEL_PASSWORD_HASH" \
  >/dev/null || die "could not store the hash"
unset PANEL_PW PANEL_PW2 PANEL_HASH
ok "hash stored in $APP_ROOT/.env; the password itself was never written anywhere"
RSH "systemctl enable liqfade-panel >/dev/null 2>&1; systemctl restart liqfade-panel" \
  || die "the panel unit would not start: journalctl -u liqfade-panel -n 50"
sleep 3
rpy panel-health || die "the panel is up but not answering on 127.0.0.1:$PANEL_PORT"
ok "panel answering on the box's loopback"
pause "Press Enter for the next stage."

# ── 11 ─────────────────────────────────────────────────────────────────────
stage "Start the recorder"
RSH "systemctl enable liqfade-recorder" >/dev/null 2>&1 || true
if RSH "systemctl is-active --quiet liqfade-recorder"; then
  ok "already running"
else
  RSH "systemctl start liqfade-recorder" || true
fi
sleep 5
if ! RSH "systemctl is-active --quiet liqfade-recorder"; then
  printf '\n'
  RSH "journalctl -u liqfade-recorder -n 30 --no-pager" || true
  printf '\n'
  note "status=203/EXEC above means systemd could not run /home/liqfade/.local/bin/uv:"
  note "the units set ProtectHome=yes, which hides /home from the service. Changing"
  note "that unit is your call, not this wizard's; ProtectHome=read-only is the fix."
  die "the recorder is not running"
fi
ok "liqfade-recorder is active"
say "Waiting for every stream to connect. Coinalyze polls once a minute, so give it one."
FEEDS_OK=""
for attempt in 1 2 3 4 5 6 7 8; do
  printf '\n'
  if rpy feeds; then FEEDS_OK=1; break; fi
  note "attempt $attempt of 8; checking again in 20s"
  sleep 20
done
if [[ -z "$FEEDS_OK" ]]; then
  RSH "journalctl -u liqfade-recorder -n 40 --no-pager" || true
  die "not every stream connected. The journal above says which venue and why."
fi
ok "every stream connected"
pause "Press Enter for the next stage."

# ── 12 ─────────────────────────────────────────────────────────────────────
stage "The panel, through the ssh tunnel"
say "The panel binds 127.0.0.1 on the VPS and nothing else, so you reach it"
say "through an ssh tunnel over $TUNNEL_VIA. Nothing is exposed."
rm -f "$TUNNEL_SOCKET"
ssh -f -N -M -S "$TUNNEL_SOCKET" -o ExitOnForwardFailure=yes -p "$SSH_PORT" "${SSH_OPTS[@]}" \
  -L "$PANEL_PORT:127.0.0.1:$PANEL_PORT" "root@$TUNNEL_HOST" \
  || die "could not open the tunnel. Is local port $PANEL_PORT already in use?"
close_tunnel() { ssh -S "$TUNNEL_SOCKET" -O exit "root@$TUNNEL_HOST" >/dev/null 2>&1 || true; }
CODE="$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:$PANEL_PORT/api/health" || true)"
if [[ "$CODE" != "200" ]]; then close_tunnel; die "the tunnel is up but /api/health answered $CODE"; fi
ok "panel reachable at http://127.0.0.1:$PANEL_PORT over $TUNNEL_VIA"
open_url "http://127.0.0.1:$PANEL_PORT"
step "Log in with the password you just chose, and open the recorder page."
step "You should see every stream connected, lag in milliseconds, and the disk gauge."
if confirm "Does the panel show all of that?"; then
  ok "panel verified over $TUNNEL_VIA"
else
  SKIPPED+=("the panel did not look right: journalctl -u liqfade-panel -n 50")
  warn "noted. The recorder keeps running either way."
fi
close_tunnel
note "reopen it any time with:"
note "  ssh -p $SSH_PORT -L $PANEL_PORT:127.0.0.1:$PANEL_PORT root@$TUNNEL_HOST"
pause "Press Enter for the next stage."

# ── 13 ─────────────────────────────────────────────────────────────────────
stage "Does Binance reach us from Tokyo?"
say "Binance geo-blocks some datacenters outright. If it blocks this one, its"
say "liquidation feed is dead weight and the config should stop weighting it."
printf '\n'
if rpy binance; then
  ok "Binance answers from this box"
else
  SKIPPED+=("Binance does not flow from this datacenter: see venues.binance in config/default.yaml")
  warn "recorded as a finding. Everything else keeps working."
fi
pause "Press Enter for the next stage."

# ── 14 ─────────────────────────────────────────────────────────────────────
stage "The recorder's own Telegram alert"
say "Stage 7 proved the credentials. This proves the path that matters: the"
say "recorder process, with the env systemd gave it, reaching Telegram by itself."
say "It raises the disk-alert flag the VPS cron uses, then clears it."
SINCE="$(date +%s)"
rpy alert-flag on || die "could not raise the flag"
say "The recorder checks disk every 5 minutes, so this can take that long."
ALERT_SEEN=""
for attempt in $(seq 1 20); do
  sleep 20
  if rpy alert-seen "$SINCE" >/dev/null 2>&1; then ALERT_SEEN=1; break; fi
  printf '  %swaiting for the alert (%s of 20)%s\r' "$DIM" "$attempt" "$RESET"
done
printf '\n'
rpy alert-flag off || warn "could not remove $APP_ROOT/data/ALERT_DISK: do it by hand"
if [[ -z "$ALERT_SEEN" ]]; then
  die "no alert_sent in the recorder's journal. Check: journalctl -u liqfade-recorder | grep alert"
fi
ok "the recorder sent an alert"
if confirm "Did it arrive in Telegram?"; then
  ok "alerting verified end to end"
else
  die "the recorder logged the send but nothing arrived: check TELEGRAM_ALERT_CHAT_ID"
fi
pause "Press Enter for the last stage."

# ── 15 ─────────────────────────────────────────────────────────────────────
stage "One Parquet file per venue"
say "The recorder holds rows in memory and writes them when the UTC hour rolls"
say "over, so the first files appear at the top of the next hour."
while :; do
  printf '\n'
  if rpy parquet; then
    ok "the lake has a file for every venue that should have one"
    break
  fi
  MINUTE="$(date -u +%M)"; SECOND="$(date -u +%S)"
  WAIT_S=$(( (59 - 10#$MINUTE) * 60 + (60 - 10#$SECOND) + 120 ))
  printf '\n'
  if confirm "Wait $(( WAIT_S / 60 )) minutes for the next flush and look again?"; then
    sleep "$WAIT_S"
  else
    SKIPPED+=("check the lake later: bash scripts/wizard_phase1_recorder.sh (it resumes here)")
    warn "fine. Re-run this wizard whenever; it walks straight back to this check."
    break
  fi
done

finish

printf '  %sThe recorder is now the only thing running that matters. Phase 1 is done\n' "$DIM"
printf '  when it has been up 48 hours with no gap over 5s. What is left is waiting,\n'
